def test_stream_request_rejects_truncated_stream_with_usage(self) -> None:
    class TruncatedResponse:
        status = 200

        def __iter__(self):
            return iter(
                [
                    b'data: {"choices":[{"delta":{"content":"partial"}}]}\n',
                    b'data: {"choices":[],"usage":{"completion_tokens":1,"prompt_tokens":10}}\n',
                ]
            )

    class TruncatedConnection:
        def __init__(self, *_args, **_kwargs):
            pass

        def request(self, *_args, **_kwargs):
            pass

        def getresponse(self):
            return TruncatedResponse()

        def close(self):
            pass

    with mock.patch.object(BENCH.http.client, "HTTPConnection", TruncatedConnection):
        result = BENCH.stream_request(
            "request-1",
            [{"role": "user", "content": "task"}],
            "model",
            8,
            10,
        )

    self.assertEqual(result["error"], "stream ended without terminal [DONE] marker")

def test_stream_request_requires_prompt_and_cached_usage(self) -> None:
    class Response:
        status = 200

        def __init__(self, usage):
            self.usage = usage

        def __iter__(self):
            return iter(
                [
                    b'data: {"choices":[{"delta":{"content":"ok"}}]}\n',
                    f'data: {json.dumps({"choices": [], "usage": self.usage})}\n'.encode(),
                    b"data: [DONE]\n",
                ]
            )

    class Connection:
        usage = {}

        def __init__(self, *_args, **_kwargs):
            pass

        def request(self, *_args, **_kwargs):
            pass

        def getresponse(self):
            return Response(self.usage)

        def close(self):
            pass

    for usage, expected in [
        ({"prompt_tokens_details": {"cached_tokens": 0}}, "prompt token usage"),
        ({"prompt_tokens": 10}, "cached token usage"),
    ]:
        with self.subTest(expected=expected):
            Connection.usage = usage
            with mock.patch.object(BENCH.http.client, "HTTPConnection", Connection):
                result = BENCH.stream_request("request", [], "model", 8, 10)
            self.assertIn(expected, result["error"])

def test_single_restore_sample_does_not_report_p95(self) -> None:
    summary = BENCH.summarize_cohort(
        "restore",
        [
            {
                "ttft_seconds": 0.2,
                "total_seconds": 0.3,
                "prompt_tokens": 10,
                "cached_tokens": 5,
                "decode_tokens_per_second": 10.0,
            }
        ],
    )

    self.assertEqual(summary["ttft_p50_seconds"], 0.2)
    self.assertIsNone(summary["ttft_p95_seconds"])

def test_prompt_manifest_preserves_trace_provenance(self):
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / "prompts.json"
        path.write_text(
            json.dumps(
                {
                    "metadata": {"dataset_revision": "pinned"},
                    "prompts": [
                        {
                            "family": "trajectory-1",
                            "bucket": "8k-16k",
                            "source_id": "session-1",
                            "prompt": "real agent trace",
                        }
                    ],
                }
            ),
            encoding="utf-8",
        )

        prompts, metadata = BENCH.read_prompt_manifest(path)

    self.assertEqual(metadata, {"dataset_revision": "pinned"})
    self.assertEqual(prompts[0]["family"], "trajectory-1")
    self.assertEqual(prompts[0]["bucket"], "8k-16k")
    self.assertEqual(prompts[0]["source_id"], "session-1")

def test_paired_intervals_are_deterministic(self):
    base = {metric: float(index + 1) for index, metric in enumerate(BENCH.METRICS)}
    cells = []
    for round_index in range(1, 5):
        cells.extend(
            [
                {"round": round_index, "version": "old", "summary": base},
                {
                    "round": round_index,
                    "version": "new",
                    "summary": {key: value * 1.1 for key, value in base.items()},
                },
            ]
        )

    first = BENCH.paired_intervals(cells, 4)
    second = BENCH.paired_intervals(cells, 4)

    self.assertEqual(first, second)
    self.assertAlmostEqual(first["makespan_ms"]["median"], 10.0)

